#include <Wire.h>
byte crc(byte a,byte b){byte v=255;byte data[]={a,b};for(int j=0;j<2;j++){v^=data[j];for(int i=0;i<8;i++)v=(v&128)?(v<<1)^49:v<<1;}return v;}
void setup(){Serial.begin(115200);Wire.begin(4,5);}
void loop(){
 Wire.beginTransmission(0x44);Wire.write(0x24);Wire.write(0);
 int ack=Wire.endTransmission();delay(20);
 if(ack||Wire.requestFrom(0x44,6)!=6){Serial.println("SHT31 NO ACK");return;}
 byte b[6];for(int i=0;i<6;i++)b[i]=Wire.read();
 if(crc(b[0],b[1])!=b[2]||crc(b[3],b[4])!=b[5]){Serial.println("CRC ERROR");return;}
 unsigned raw=(unsigned(b[0])<<8)|b[1];
 Serial.print("TEMP x100=");Serial.print(int(raw*17500u/65535u)-4500);
 Serial.print(" HUM x100=");Serial.println(((unsigned(b[3])<<8)|b[4])*10000u/65535u);
}

