const unsigned DQ=4;
void pullLow(){digitalWrite(DQ,LOW);pinMode(DQ,OUTPUT);}
void release(){pinMode(DQ,INPUT);}
bool resetBus(){pullLow();delayMicroseconds(500);release();delayMicroseconds(70);bool present=!digitalRead(DQ);delayMicroseconds(430);return present;}
void writeByte(byte value){for(int i=0;i<8;i++){pullLow();delayMicroseconds(value&1?6:60);release();delayMicroseconds(value&1?64:10);value>>=1;}}
byte readByte(){byte value=0;for(int i=0;i<8;i++){pullLow();delayMicroseconds(6);release();delayMicroseconds(9);value|=digitalRead(DQ)<<i;delayMicroseconds(55);}return value;}
byte crc8(byte*data){byte crc=0;for(int n=0;n<8;n++){byte value=data[n];for(int b=0;b<8;b++){byte mix=(crc^value)&1;crc>>=1;if(mix)crc^=0x8C;value>>=1;}}return crc;}
void setup(){Serial.begin(115200);release();resetBus();writeByte(0xCC);writeByte(0x4E);writeByte(75);writeByte(70);writeByte(0x1F);}
void loop(){if(!resetBus()){Serial.println("DS18B20 NO PRESENCE");delay(20);return;}writeByte(0xCC);writeByte(0x44);delay(100);resetBus();writeByte(0xCC);writeByte(0xBE);byte data[9];for(int i=0;i<9;i++)data[i]=readByte();if(crc8(data)!=data[8]){Serial.println("DS18B20 CRC ERROR");return;}int raw=(data[1]<<8)|data[0];if(raw&32768)raw-=65536;Serial.print("DS TEMP x100=");Serial.println(raw*100/16);}

